{{--
  "Print" in the tools menu: only the table — the rows on screen, as shown,
  not the page around it — like @acunsoft/datatable-dom's printRows(). The
  table's columns are copied into a hidden frame with the page's stylesheets,
  printed, and the frame is removed afterwards. Printed inside an attribute,
  so the script uses single quotes only.
--}}
(async () => { const root = $el.closest('.adt'); const source = root?.querySelector('table.adt-table'); const head = source?.tHead?.rows[source.tHead.rows.length - 1]; if (! source || ! head) return; const keep = [...head.cells].map((cell, index) => ({ cell, index })).filter(item => item.cell.matches('th.adt-th:not(.adt-actions)')); const frame = document.createElement('iframe'); frame.setAttribute('aria-hidden', 'true'); frame.tabIndex = -1; frame.style.cssText = 'position:fixed;right:0;bottom:0;width:0;height:0;border:0;visibility:hidden'; document.body.append(frame); const view = frame.contentWindow; const page = frame.contentDocument; page.documentElement.lang = document.documentElement.lang; page.documentElement.setAttribute('data-theme', 'light'); page.title = document.title; const loading = []; for (const sheet of document.querySelectorAll('link[rel~=stylesheet], style')) { const copy = page.importNode(sheet, true); if (copy.tagName === 'LINK') loading.push(new Promise(resolve => { copy.addEventListener('load', resolve); copy.addEventListener('error', resolve); })); page.head.append(copy); } const own = page.createElement('style'); own.textContent = ['html,body{background:#fff;color:#111}', 'body{margin:0;padding:12mm;font:11pt/1.45 system-ui,-apple-system,sans-serif}', 'h1{margin:0 0 2mm;font-size:15pt}', '.adt-print-subtitle{margin:0 0 5mm;color:#555;font-size:9pt}', '.adt-print{width:100%;border-collapse:collapse}', '.adt-print th,.adt-print td{padding:5px 8px;border-bottom:1px solid #d6d9de;text-align:left;vertical-align:top}', '.adt-print th{font-size:8.5pt;letter-spacing:.04em;text-transform:uppercase;color:#444;border-bottom-color:#999}', '.adt-print .adt-num{text-align:right;font-variant-numeric:tabular-nums}', '.adt-print thead{display:table-header-group}', '.adt-print tr{break-inside:avoid}', String.fromCharCode(64) + 'page{margin:0}'].join(String.fromCharCode(10)); page.head.append(own); const title = page.createElement('h1'); title.textContent = document.title; const info = page.createElement('p'); info.className = 'adt-print-subtitle'; info.textContent = [root.querySelector('.adt-info')?.textContent.trim(), new Date().toLocaleString(document.documentElement.lang || undefined)].filter(Boolean).join(' · '); const table = page.createElement('table'); table.className = 'adt-print'; const thead = table.createTHead().insertRow(); for (const { cell } of keep) { const copy = cell.cloneNode(true); copy.querySelectorAll('.adt-sort-mark, .adt-resize, svg').forEach(node => node.remove()); const th = page.createElement('th'); th.scope = 'col'; if (cell.classList.contains('adt-num')) th.className = 'adt-num'; th.textContent = copy.textContent.trim(); thead.append(th); } const tbody = table.createTBody(); for (const row of source.querySelectorAll('tbody tr.adt-row')) { if (row.cells.length !== head.cells.length) continue; const tr = tbody.insertRow(); for (const { cell, index } of keep) { const td = tr.insertCell(); if (cell.classList.contains('adt-num')) td.className = 'adt-num'; const shown = row.cells[index].querySelector('.adt-edit-value') ?? row.cells[index]; const copy = page.importNode(shown, true); copy.querySelectorAll('button, input, select, textarea, dialog, .adt-edit-message').forEach(node => node.remove()); td.append(...copy.childNodes); } } page.body.append(title, info, table); await Promise.all(loading); const done = () => frame.remove(); view.addEventListener('afterprint', () => setTimeout(done)); setTimeout(done, 60000); view.focus(); view.print(); })()
